mapper.select:


    inner join sys_user u on u.user_name = ttray.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'

left join t_area ta on ta.id=ttray.area_id
left join t_location tl on tl.id=ttray.location_id
left join t_reservoir tr on tr.id=ttray.reservoir_id

    ttray.del_flag = '0'
    and ttray.code like concat('%', #{code}, '%')
    and ttray.area_id = #{areaId}
    and ttray.location_id = #{locationId}
    and ttray.reservoir_id = #{reservoirId}
    and ttray.type = #{type}
    and ttray.status = #{status}
    and ttray.tray_category = #{trayCategory}
    and ttray.label_template_type =
        #{labelTemplateType}

    and ttray.label_template_id = #{labelTemplateId}
    and ttray.status <> #{notStatus}


${params.dataScope}

select ttray.id, ttray.code, ttray.area_id, ttray.location_id, ttray.reservoir_id, ttray.type, ttray.status,
ttray.tray_category, ttray.label_template_type, ttray.label_template_id, ttray.remark, ttray.create_by,
ttray.create_time, ttray.update_by, ttray.update_time, ttray.dept_id, ttray.dept_name, ttray.del_flag,
ttray.weight, ttray.max_weight,
tl.name as locationName,tl.goods_allocation_status,tl.pallet_num
from t_tray ttray
left join t_location tl on ttray .location_id = tl.id

    inner join sys_user u on u.user_name = ttray.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    ttray.del_flag = '0'
    and ttray.code like concat('%', #{code}, '%')
    and ttray.area_id = #{areaId}
    and ttray.location_id = #{locationId}
    and ttray.reservoir_id = #{reservoirId}
    and ttray.type = #{type}
    and ttray.status = #{status}
    and ttray.tray_category = #{trayCategory}
    and ttray.label_template_type =
        #{labelTemplateType}

    and ttray.label_template_id = #{labelTemplateId}
    and ttray.status <> #{notStatus}
    and (ttray .location_id is null or (ttray .location_id is
        not null and tl.location_type= '0'))

    and tl.goods_allocation_status =
        #{goodsAllocationStatus}

    and tl.name like concat('%', #{locationName}, '%')


${params.dataScope}
order by ttray.create_time desc
